mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, sys, urllib.request, urllib.error
BASE = "http://localhost:8080"
tok = None
log = []
def token():
    global tok
    r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", method="POST", data=b""))
    tok = json.load(r)["token"]
def get(path):
    attempts = 0
    while True:
        attempts += 1
        if attempts > 200: raise RuntimeError("too many attempts " + path)
        if tok is None: token()
        req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + tok})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            body = r.read()
            try:
                return 200, json.loads(body)
            except Exception as e:
                log.append((path, "badjson", body[:200])); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            body = e.read()
            log.append((path, e.code, body[:200].decode(errors="replace"), dict(e.headers).get("Retry-After")))
            if e.code == 401: token(); continue
            if e.code == 429:
                ra = e.headers.get("Retry-After")
                try: ra = float(ra)
                except: ra = json.loads(body).get("retry_after", 1)
                time.sleep(float(ra)); continue
            if e.code == 404: return 404, body.decode(errors="replace")
            time.sleep(0.5); continue
        except Exception as e:
            log.append((path, "exc", repr(e))); time.sleep(0.5); continue
pages = {}
path = "/orders?page=1"
while path:
    st, d = get(path)
    assert st == 200, (path, d)
    pages[d["page"]] = d
    print(path, d["page"], d["total_pages"], len(d["items"]), d["next"], file=sys.stderr)
    path = d["next"]
json.dump(pages, open("/tmp/recon/pages.json", "w"))
cids = sorted({i["customer_id"] for p in pages.values() for i in p["items"]})
custs = {}
for c in cids:
    custs[c] = get("/customers/" + c)
json.dump(custs, open("/tmp/recon/customers.json", "w"))
json.dump(log, open("/tmp/recon/log.json", "w"), default=str)
print("errors:", len(log), file=sys.stderr)
EOF
python3 -I /tmp/recon/fetch.py

